/* Get the ETHERNET_CONFIG APP version */
ACS_APP_VERSION_t ETHERNET_CONFIG_GetAppVersion()
{
  ACS_APP_VERSION_t version;

  version.major = ETHERNET_CONFIG_MAJOR_VERSION;
  version.minor = ETHERNET_CONFIG_MINOR_VERSION;
  version.patch = ETHERNET_CONFIG_PATCH_VERSION;

  return version;
}

/* Function to initialize the GETH module by the configuration made in GUI */
ETHERNET_CONFIG_STATUS_t ETHERNET_CONFIG_Init(ETHERNET_CONFIG_t *handle)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, ((handle != NULL) && (handle->app_config != NULL)));
  ETHERNET_CONFIG_STATUS_t status = ETHERNET_CONFIG_STATUS_SUCCESS;

  if (!handle->app_is_initialized)
  {
    if (CPU_CORE_Init(handle->cpu_core_handle) == CPU_CORE_STATUS_SUCCESS)
    {
      /* Initialize the GETH module */
      IfxGeth_Eth_initModule(handle->geth_module, handle->app_config->geth_lld_config);

      handle->geth_module->gethSFR->MAC_PACKET_FILTER.U = 0;

#if ETHERNET_CONFIG_TAIL_POINTER_ENABLED
      /* Fix to make descriptor pointed by TAIL pointer inside the descriptor list */
      for (uint32 rx_channel_index = 0; rx_channel_index < handle->app_config->geth_lld_config->dma.numOfRxChannels; rx_channel_index++)
      {
        handle->app_config->dma_config->geth_rx_desc[rx_channel_index][ETHERNET_CONFIG_RX_DESCRIPTORS_MAX - 1].RDES3.U = 0;
        IfxGeth_dma_setRxDescriptorTailPointer(
                handle->geth_module->gethSFR,
                (IfxGeth_RxDmaChannel)rx_channel_index,
                (uint32)&handle->app_config->dma_config->geth_rx_desc[rx_channel_index][ETHERNET_CONFIG_RX_DESCRIPTORS_MAX - 1]);
      }

      for (uint32 tx_channel_index = 0; tx_channel_index < handle->app_config->geth_lld_config->dma.numOfTxChannels; tx_channel_index++)
      {
        IfxGeth_dma_setTxDescriptorTailPointer(
                handle->geth_module->gethSFR,
                (IfxGeth_TxDmaChannel)tx_channel_index,
                (uint32)&handle->app_config->dma_config->geth_tx_desc[tx_channel_index][0]);
      }
#endif

      IfxGeth_Eth_startReceivers(handle->geth_module,
                                 handle->app_config->geth_lld_config->dma.numOfRxChannels);
      IfxGeth_Eth_startTransmitters(handle->geth_module,
                                    handle->app_config->geth_lld_config->dma.numOfTxChannels);

      handle->app_is_initialized = TRUE;
    }
    else
    {
      status = ETHERNET_CONFIG_STATUS_FAILURE;
    }
  }

  return status;
}

/* Prepare and return RX descriptor to DMA. */
void ETHERNET_CONFIG_ReturnRxDescriptor(ETHERNET_CONFIG_t *handle, IfxGeth_RxDescr *desc, uint8 *buffer)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, ((handle != NULL) && (handle->app_config != NULL)));

  desc->RDES0.U = (uint32)buffer;
  desc->RDES3.U = (1UL << 31) |  /* OWN */
                  (1UL << 30) |  /* IOC */
                  (1UL << 24);   /* BUF1V */
}

/* Obtain the next descriptor in the RX descriptor list. */
IfxGeth_RxDescr *ETHERNET_CONFIG_GetNextRxDescriptor(ETHERNET_CONFIG_t *handle, IfxGeth_RxDescr *desc)
{
  IFX_ASSERT(IFX_VERBOSE_LEVEL_FAILURE, ((handle != NULL) && (handle->app_config != NULL)));

  Ifx_GETH *gethSFR = handle->geth_module->gethSFR;
  IfxGeth_RxDmaChannel channelId = handle->app_config->geth_lld_config->dma.rxChannel->channelId;

  IfxGeth_RxDescr *const baseDescr = (IfxGeth_RxDescr *const)gethSFR->DMA_CH[channelId].RXDESC_LIST_ADDRESS.U;
  const int num_descs = ETHERNET_CONFIG_GetSizeRxDescriptorList(handle);
  IfxGeth_RxDescr *const lastDescr = &baseDescr[num_descs];

  /* update tail pointer */
  desc++;
  if (desc == lastDescr)
  {
    /* wrap around the descriptors */
    desc = baseDescr;
  }

  return desc;
}

